class SettingsCase(unittest.TestCase):
    """Gives every test `self.conf`, the fallback settings with caching off,
    and `self.make(**values)` for settings that differ from it. Caching is
    off so that results from one test are never reused by another."""

    def setUp(self) -> None:
        self.conf = self.make()

    def make(self, **values):
        values.setdefault("cache_enabled", False)
        return settings.make(**values)
